const DEFAULT_FIELDS: &[&str] = &["title", "isbn"];

/// Lucene's `Query.toString()`. An open range bound prints inclusive.
fn lucene_string(node: &Node) -> String {
    match node {
        Node::Term { field, text } => format!("{field}:{text}"),
        Node::Phrase { field, terms, slop } => {
            let last = terms.last().map_or(0, |(position, _)| *position);
            let mut pieces = vec!["?".to_owned(); last + 1];
            for (position, text) in terms {
                pieces[*position] = text.clone();
            }
            let slop = if *slop == 0 {
                String::new()
            } else {
                format!("~{slop}")
            };
            format!("{field}:\"{}\"{slop}", pieces.join(" "))
        }
        Node::Boolean(clauses) => {
            let clauses: Vec<String> = clauses
                .iter()
                .map(|(occur, node)| {
                    let occur = match occur {
                        Occur::Must => "+",
                        Occur::Should => "",
                        Occur::MustNot => "-",
                    };
                    match node {
                        Node::Boolean(_) => format!("{occur}({})", lucene_string(node)),
                        _ => format!("{occur}{}", lucene_string(node)),
                    }
                })
                .collect();
            clauses.join(" ")
        }
        Node::Boost(node, boost) => format!("({})^{boost:?}", lucene_string(node)),
        Node::MatchAll => "*:*".to_owned(),
        Node::Prefix { field, text } => format!("{field}:{text}*"),
        Node::Wildcard { field, pattern } => format!("{field}:{pattern}"),
        Node::Regexp { field, pattern } => format!("{field}:/{pattern}/"),
        Node::Fuzzy { field, text, edits } => format!("{field}:{text}~{edits}"),
        Node::Range {
            field,
            lower,
            upper,
        } => {
            let lower = match lower {
                Bound::Included(text) => format!("[{text}"),
                Bound::Excluded(text) => format!("{{{text}"),
                Bound::Unbounded => "[*".to_owned(),
            };
            let upper = match upper {
                Bound::Included(text) => format!("{text}]"),
                Bound::Excluded(text) => format!("{text}}}"),
                Bound::Unbounded => "*]".to_owned(),
            };
            format!("{field}:{lower} TO {upper}")
        }
    }
}

fn komga_query(text: &str) -> String {
    match parse(text, DEFAULT_FIELDS) {
        Ok(node) => lucene_string(&node),
        Err(InvalidQuery) => "INVALID".to_owned(),
    }
}

#[test]
fn queries_parse_as_lucene_parses_them() {
    for (text, lucene) in LUCENE_QUERIES {
        let parsed = match parse_lucene(&format!("{text} *:*"), DEFAULT_FIELDS) {
            Ok(node) => node.as_ref().map_or_else(String::new, lucene_string),
            Err(InvalidQuery) => "INVALID".to_owned(),
        };
        assert_eq!(parsed, *lucene, "query {text:?}");
    }
}

#[test]
fn the_appended_match_all_only_serves_negative_queries() {
    let cases = [
        ("batman", "+(title:batman isbn:batman)"),
        (
            "batman OR superman",
            "(title:batman isbn:batman) (title:superman isbn:superman)",
        ),
        ("a OR", "(title:a isbn:a)"),
        ("-batman", "-(title:batman isbn:batman) +*:*"),
        ("-a OR -b", "-(title:a isbn:a) -(title:b isbn:b) +*:*"),
        (".", "+*:*"),
        ("", "*:*"),
    ];
    for (text, expected) in cases {
        assert_eq!(komga_query(text), expected, "query {text:?}");
    }
}

#[test]
fn negative_groups_match_everything_but_their_exclusions() {
    assert_eq!(
        komga_query("title:(-batman) superman"),
        "+(-title:batman +*:*) +(title:superman isbn:superman)"
    );
}

#[test]
fn oversized_queries_are_invalid() {
    let words = vec!["a"; 600].join(" ");
    let nested = format!("{}a{}", "(".repeat(101), ")".repeat(101));

    assert_eq!(komga_query(&words), "INVALID");
    assert_eq!(komga_query(&nested), "INVALID");
    assert_eq!(
        komga_query(&format!("{}a{}", "(".repeat(99), ")".repeat(99))),
        "+(title:a isbn:a)"
    );
}
